import '../config/app_config.dart'; import '../config/supabase_config.dart'; import '../models/follow_counts.dart';
class FollowRepository { final c=SupabaseConfig.client; Future<FollowCounts>counts(String userId)async{if(AppConfig.demoMode)return const FollowCounts(0,0);final r=await c.rpc('get_follow_counts',params:{'p_user_id':userId});return FollowCounts((r['followers_count']??0)as int,(r['following_count']??0)as int);} Future<bool>isFollowing(String id)async{if(AppConfig.demoMode)return false;return await c.rpc('is_following',params:{'p_user_id':id}) as bool;} Future<void>follow(String id)async{if(!AppConfig.demoMode)await c.rpc('follow_user',params:{'p_user_id':id});} Future<void>unfollow(String id)async{if(!AppConfig.demoMode)await c.rpc('unfollow_user',params:{'p_user_id':id});}}
